package cz.ioff.app;

import android.app.*;import android.app.usage.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.provider.Settings;import android.speech.RecognizerIntent;import android.view.*;import android.widget.*;import org.json.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity{
 final int BG=Color.rgb(8,10,14),CARD=Color.rgb(20,23,30),CARD2=Color.rgb(29,33,42),INK=Color.rgb(246,247,250),MUTED=Color.rgb(155,163,177),ACCENT=Color.rgb(126,255,174),DANGER=Color.rgb(255,115,115); SharedPreferences p; LinearLayout root,content; CountDownTimer timer; int urges; long left; final int VOICE=7;
 String[] days={"BASELINE","REMOVE TRIGGERS","TRAIN BOREDOM","OWN YOUR MORNING","BREAK THE FEED","GO DEEP","SILENCE & MEASURE"};
 String[] missions={"60 min on one important thing. Measure, don't judge.","Remove triggers. Complete two 60 min focus blocks.","30 min without input. Then focus.","90 min deep work before feeds, news or email.","24 hours without algorithmic feeds.","One problem. 120 minutes. Park every side idea.","Three low-input hours, then review what changed."};
 public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("ioff",0);recover();showToday();}
 int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);} GradientDrawable shape(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;} TextView tx(String s,int z,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(INK);v.setPadding(0,dp(6),0,dp(6));if(b)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;} TextView mu(String s,int z){TextView v=tx(s,z,false);v.setTextColor(MUTED);return v;} Button button(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(null,Typeface.BOLD);b.setTextColor(primary?BG:INK);b.setBackground(shape(primary?ACCENT:CARD2,16));return b;} LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(18),dp(16),dp(18),dp(16));c.setBackground(shape(CARD,20));LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(-1,-2);l.setMargins(0,dp(8),0,dp(8));c.setLayoutParams(l);return c;}
 void base(String section){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(20),dp(16),dp(20),dp(24));ScrollView s=new ScrollView(this);s.addView(content);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);String[] n={"Today","Focus","Ideas","Progress","Control"};for(String x:n){Button b=button(x,false);b.setTextSize(11);b.setBackgroundColor(Color.TRANSPARENT);b.setTextColor(MUTED);b.setOnClickListener(v->{if(x.equals("Today"))showToday();else if(x.equals("Focus"))showFocus();else if(x.equals("Ideas"))showIdeas();else if(x.equals("Progress"))showProgress();else showControl();});nav.addView(b,new LinearLayout.LayoutParams(0,dp(58),1));}root.addView(nav);setContentView(root);LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);TextView logo=tx("iOff",30,true);logo.setTextColor(ACCENT);h.addView(logo,new LinearLayout.LayoutParams(0,-2,1));h.addView(mu(section,11));content.addView(h);}
 int day(){return Math.max(1,Math.min(7,p.getInt("day",1)));} String date(){return new SimpleDateFormat("yyyyMMdd",Locale.US).format(new Date());} String dk(String k){return k+"_"+date();} int today(String k){return p.getInt(dk(k),0);} void inc(String k,int n){p.edit().putInt(dk(k),today(k)+n).apply();} int total(String k){int n=0;for(String key:p.getAll().keySet())if(key.startsWith(k+"_")){Object v=p.getAll().get(key);if(v instanceof Integer)n+=(Integer)v;}return n;} String dots(){StringBuilder s=new StringBuilder();for(int i=1;i<=7;i++)s.append(i<=day()?"● ":"○ ");return s.toString();}
 void showToday(){base("TODAY");content.addView(tx("OWN YOUR\nATTENTION.",35,true));content.addView(mu("Day "+day()+" of 7 · deliberate attention reset",14));TextView d=tx(dots(),20,true);d.setTextColor(ACCENT);content.addView(d);LinearLayout m=card();m.addView(mu("TODAY'S MISSION",11));TextView q=tx(days[day()-1],23,true);q.setTextColor(ACCENT);m.addView(q);m.addView(mu(missions[day()-1],15));content.addView(m);Button f=button("START FOCUS →",true);f.setOnClickListener(v->showFocus());content.addView(f);LinearLayout st=card();st.addView(mu("TODAY",11));st.addView(tx(today("mins")+" min  ·  "+today("urges")+" urges  ·  "+today("sessions")+" sessions",18,true));long u=usageToday();if(u>=0)st.addView(mu("Distracting apps: "+(u/60000)+" min",13));content.addView(st);Button idea=button("＋ PARK IDEA",false);idea.setOnClickListener(v->ideaDialog());content.addView(idea);LinearLayout row=new LinearLayout(this);Button prev=button("← Previous",false);prev.setEnabled(day()>1);prev.setOnClickListener(v->{p.edit().putInt("day",day()-1).apply();showToday();});Button next=button(day()==7?"DAY 7":"Complete →",false);next.setOnClickListener(v->{if(day()<7)p.edit().putInt("day",day()+1).apply();showToday();});row.addView(prev,new LinearLayout.LayoutParams(0,dp(54),1));row.addView(next,new LinearLayout.LayoutParams(0,dp(54),1));content.addView(row);}
 void showFocus(){if(p.getBoolean("focus_active",false)){resumeFocus();return;}base("FOCUS");content.addView(tx("ONE THING.\nUNTIL IT'S DONE.",31,true));LinearLayout c=card();c.addView(mu("WHAT WILL EXIST WHEN YOU FINISH?",11));EditText goal=new EditText(this);goal.setTextColor(INK);goal.setHintTextColor(MUTED);goal.setHint("One concrete output");goal.setText(p.getString("goal",""));c.addView(goal);content.addView(c);LinearLayout row=new LinearLayout(this);for(int n:new int[]{30,60,90,120}){Button b=button(n+"m",false);b.setOnClickListener(v->{p.edit().putInt("duration",n).apply();Toast.makeText(this,n+" min selected",0).show();});row.addView(b,new LinearLayout.LayoutParams(0,dp(54),1));}content.addView(row);Button start=button("BEGIN FOCUS →",true);start.setOnClickListener(v->{String g=goal.getText().toString().trim();if(g.isEmpty()){goal.setError("Define the output first");return;}p.edit().putString("goal",g).apply();startFocus(p.getInt("duration",60));});content.addView(start);}
 void startFocus(int mins){long now=System.currentTimeMillis(),end=now+mins*60000L;urges=0;p.edit().putBoolean("focus_active",true).putLong("focus_start",now).putLong("focus_end",end).putInt("focus_planned",mins).putInt("focus_urges",0).apply();enableDnd();resumeFocus();}
 void resumeFocus(){long end=p.getLong("focus_end",0);if(end<=System.currentTimeMillis()){finishFocus(false);return;}base("FOCUS SESSION");TextView clock=tx("",52,true);clock.setTextColor(ACCENT);clock.setGravity(Gravity.CENTER);content.addView(clock);TextView g=tx(p.getString("goal",""),20,true);g.setGravity(Gravity.CENTER);content.addView(g);TextView shield=mu("SHIELD ON · DND "+(dndGranted()?"ON":"PERMISSION NEEDED"),12);shield.setGravity(Gravity.CENTER);content.addView(shield);TextView uc=mu(p.getInt("focus_urges",0)+" urges",15);uc.setGravity(Gravity.CENTER);content.addView(uc);Button u=button("I FEEL AN URGE",false);u.setOnClickListener(v->{int x=p.getInt("focus_urges",0)+1;p.edit().putInt("focus_urges",x).apply();uc.setText(x+" urges");});content.addView(u);Button idea=button("＋ PARK IDEA",false);idea.setOnClickListener(v->ideaDialog());content.addView(idea);Button endb=button("End session early",false);endb.setTextColor(DANGER);endb.setOnClickListener(v->{if(timer!=null)timer.cancel();finishFocus(true);});content.addView(endb);left=end-System.currentTimeMillis();timer=new CountDownTimer(left,1000){public void onTick(long ms){left=ms;clock.setText(String.format(Locale.US,"%02d:%02d:%02d",ms/3600000,(ms/60000)%60,(ms/1000)%60));}public void onFinish(){finishFocus(false);}}.start();}
 void finishFocus(boolean interrupted){long start=p.getLong("focus_start",System.currentTimeMillis());int actual=(int)Math.max(0,(System.currentTimeMillis()-start)/60000L),planned=p.getInt("focus_planned",60),u=p.getInt("focus_urges",0);if(!interrupted)actual=Math.max(actual,planned);restoreDnd();p.edit().putBoolean("focus_active",false).apply();base("SESSION COMPLETE");TextView big=tx(actual+" MIN",38,true);big.setTextColor(ACCENT);content.addView(big);EditText out=new EditText(this);out.setTextColor(INK);out.setHintTextColor(MUTED);out.setHint("What did you produce?");content.addView(out);content.addView(mu("FOCUS QUALITY",11));SeekBar score=new SeekBar(this);score.setMax(9);score.setProgress(6);content.addView(score);Button save=button("SAVE SESSION",true);final int a=actual,uu=u;save.setOnClickListener(v->{saveSession(start,System.currentTimeMillis(),planned,a,uu,score.getProgress()+1,interrupted,out.getText().toString());showToday();});content.addView(save);}
 void saveSession(long s,long e,int planned,int actual,int u,int score,boolean interrupted,String output){inc("mins",actual);inc("urges",u);inc("sessions",1);p.edit().putInt(dk("focusSum"),today("focusSum")+score).putInt("last_focus",score).apply();try{JSONArray a=new JSONArray(p.getString("sessions_json","[]"));JSONObject o=new JSONObject();o.put("start",s);o.put("end",e);o.put("date",date());o.put("experimentDay",day());o.put("planned",planned);o.put("actual",actual);o.put("urges",u);o.put("focus",score);o.put("interrupted",interrupted);o.put("goal",p.getString("goal",""));o.put("output",output);a.put(o);p.edit().putString("sessions_json",a.toString()).apply();}catch(Exception ignored){}}
 void recover(){if(p.getBoolean("focus_active",false)&&p.getLong("focus_end",0)<=System.currentTimeMillis())restoreDnd();}
 boolean dndGranted(){NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);return n!=null&&n.isNotificationPolicyAccessGranted();} void enableDnd(){NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(n!=null&&n.isNotificationPolicyAccessGranted()){p.edit().putInt("prev_filter",n.getCurrentInterruptionFilter()).apply();n.setInterruptionFilter(NotificationManager.INTERRUPTION_FILTER_PRIORITY);}} void restoreDnd(){NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(n!=null&&n.isNotificationPolicyAccessGranted())try{n.setInterruptionFilter(p.getInt("prev_filter",NotificationManager.INTERRUPTION_FILTER_ALL));}catch(Exception ignored){}p.edit().putBoolean("focus_active",false).apply();}
 void ideaDialog(){EditText x=new EditText(this);x.setHint("Get it out of your head…");new AlertDialog.Builder(this).setTitle("Park idea").setView(x).setNeutralButton("VOICE",(d,w)->voice()).setNegativeButton("Cancel",null).setPositiveButton("PARK",(d,w)->park(x.getText().toString())).show();} void park(String s){s=s.trim();if(s.isEmpty())return;String old=p.getString("ideas","");p.edit().putString("ideas",System.currentTimeMillis()+"|"+s+"\n"+old).apply();inc("ideasCount",1);} void voice(){try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);startActivityForResult(i,VOICE);}catch(Exception e){Toast.makeText(this,"Voice recognition unavailable",0).show();}} protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(r==VOICE&&c==RESULT_OK&&data!=null){ArrayList<String>x=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(x!=null&&!x.isEmpty())park(x.get(0));}}
 int countIdeas(){String s=p.getString("ideas","").trim();return s.isEmpty()?0:s.split("\\n").length;} void showIdeas(){base("IDEAS");content.addView(tx("PARK IT.\nDON'T CHASE IT.",30,true));Button add=button("＋ PARK IDEA / VOICE",true);add.setOnClickListener(v->ideaDialog());content.addView(add);String s=p.getString("ideas","");if(s.trim().isEmpty())content.addView(mu("Parking lot is empty.",16));else for(String line:s.split("\\n")){String[]z=line.split("\\|",2);if(z.length==2){LinearLayout c=card();c.addView(tx(z[1],16,true));try{c.addView(mu(new SimpleDateFormat("dd/MM · HH:mm",Locale.getDefault()).format(new Date(Long.parseLong(z[0]))),12));}catch(Exception ignored){}content.addView(c);}}}
 long usageToday(){try{UsageStatsManager u=(UsageStatsManager)getSystemService(USAGE_STATS_SERVICE);Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);long n=0;Set<String>b=p.getStringSet("blocked_apps",new HashSet<>(Arrays.asList("com.instagram.android","com.facebook.katana","com.zhiliaoapp.musically","com.google.android.youtube","com.twitter.android","com.reddit.frontpage")));for(UsageStats s:u.queryUsageStats(UsageStatsManager.INTERVAL_DAILY,c.getTimeInMillis(),System.currentTimeMillis()))if(b.contains(s.getPackageName()))n+=s.getTotalTimeInForeground();return n;}catch(Exception e){return-1;}}
 void showProgress(){base("PROGRESS");int mins=total("mins"),sessions=total("sessions"),u=total("urges"),sum=total("focusSum");content.addView(tx("MEASURE CHANGE,\nNOT STREAKS.",29,true));LinearLayout c=card();TextView x=tx(mins+" MIN",38,true);x.setTextColor(ACCENT);c.addView(x);c.addView(mu("total deep work · "+sessions+" sessions",14));content.addView(c);LinearLayout a=card();a.addView(tx(sessions==0?"—":String.format(Locale.US,"%.1f / 10",sum/(double)sessions),25,true));a.addView(mu("average focus quality",14));content.addView(a);LinearLayout b=card();b.addView(tx(mins==0?"—":String.format(Locale.US,"%.1f",u/(mins/60.0))+" / h",25,true));b.addView(mu("urges per focus hour",14));content.addView(b);if(day()==7){LinearLayout r=card();r.addView(mu("DAY 7 · BEFORE → AFTER",11));r.addView(tx("Your report is now built from real session history.",18,true));r.addView(mu("Baseline and current behavior stay local on this phone.",13));content.addView(r);}}
 void showControl(){base("CONTROL");content.addView(tx("DESIGN YOUR\nENVIRONMENT.",30,true));LinearLayout s=card();s.addView(mu("PROTECTION",11));s.addView(tx("Focus Shield  ·  "+(p.getBoolean("shield_enabled",true)?"ON":"OFF"),17,true));Switch sh=new Switch(this);sh.setText("Enable app friction");sh.setTextColor(INK);sh.setChecked(p.getBoolean("shield_enabled",true));sh.setOnCheckedChangeListener((b,c)->p.edit().putBoolean("shield_enabled",c).apply());s.addView(sh);Switch mo=new Switch(this);mo.setText("Morning protection until 09:00");mo.setTextColor(INK);mo.setChecked(p.getBoolean("morning_shield",true));mo.setOnCheckedChangeListener((b,c)->p.edit().putBoolean("morning_shield",c).apply());s.addView(mo);content.addView(s);LinearLayout access=card();access.addView(mu("ANDROID ACCESS",11));Button d=button("DND access →",false);d.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_NOTIFICATION_POLICY_ACCESS_SETTINGS)));access.addView(d);Button u=button("Usage access →",false);u.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS)));access.addView(u);Button ac=button("Shield accessibility →",false);ac.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));access.addView(ac);content.addView(access);LinearLayout ex=card();ex.addView(tx("Experiment day: "+day()+" / 7",17,true));Button choose=button("Choose day",false);choose.setOnClickListener(v->chooseDay());ex.addView(choose);Button reset=button("Reset experiment & stats",false);reset.setTextColor(DANGER);reset.setOnClickListener(v->confirmReset());ex.addView(reset);content.addView(ex);content.addView(mu("Local-first. No account, cloud or feed.",13));}
 void chooseDay(){String[]x=new String[7];for(int i=0;i<7;i++)x[i]="Day "+(i+1)+" — "+days[i];new AlertDialog.Builder(this).setTitle("Go to day").setSingleChoiceItems(x,day()-1,(d,w)->{p.edit().putInt("day",w+1).apply();d.dismiss();showToday();}).show();} void confirmReset(){new AlertDialog.Builder(this).setTitle("Reset iOff?").setMessage("Clears experiment and focus history.").setNegativeButton("Cancel",null).setNeutralButton("Keep ideas",(d,w)->reset(false)).setPositiveButton("Reset everything",(d,w)->reset(true)).show();} void reset(boolean all){restoreDnd();String ideas=p.getString("ideas","");p.edit().clear().apply();if(!all&&!ideas.isEmpty())p.edit().putString("ideas",ideas).apply();showToday();}
 protected void onDestroy(){if(timer!=null)timer.cancel();super.onDestroy();}
}
